-- Khóa học chuyên sâu theo bộ slide chính thức "Giới thiệu STEMLab" (slide 35–42), API 21.
-- SINH BẰNG MÁY từ cùng dữ liệu với src/i18n (vi.js / en.js / intensiveDetails.*.js).
--
-- 1. Section `courses`, mỗi ngôn ngữ MỘT câu UPDATE (`rev` +1 mỗi câu → +2), chốt theo TỪNG
--    ngôn ngữ bằng id 'the-gioi-robot' (chạy lại không đổi gì):
--    - `items`: giữ nguyên mọi mục KHÔNG thuộc nhóm 'stem' theo thứ tự cũ (30 chương trình
--      trải nghiệm đã khớp slide), bỏ 4 khóa STEM cũ của website trước, nối 7 khóa mới;
--    - `stages`: thêm cấp 'th-thcs' nếu chưa có;
--    - mô tả nhóm stem chỉ đổi khi còn NGUYÊN VĂN cũ (admin đã sửa thì giữ);
--    - nhãn `comingSoon`.
-- 2. `course_detail`: popup (đối tượng + 8 buổi), nguồn 'handwritten'. Chốt `EXISTS section`:
--    trên database trống migration chạy TRƯỚC seed, và seed tự chèn các dòng này.
-- 3. `binding`: dùng lại ảnh THẬT đang gắn cho một khóa / chương trình cùng chủ đề (ghi chú `~`).
--    Ảnh của 4 khóa cũ giữ nguyên (mồ côi có chủ đích — tạo lại đúng id là ảnh về chỗ).

-- vi
UPDATE section
   SET json = json_set(CASE WHEN (SELECT '$.groups[' || key || '].description' FROM json_each(section.json, '$.groups') WHERE json_extract(value, '$.id') = 'stem' AND json_extract(value, '$.description') = 'Chương trình đầy đủ 5–10 tuần, theo một dự án từ bản phác đầu tiên đến sản phẩm hoàn thiện.') IS NOT NULL THEN json_set(CASE WHEN EXISTS (SELECT 1 FROM json_each(section.json, '$.stages') WHERE json_extract(value, '$.id') = 'th-thcs') THEN json_set(json, '$.items', (SELECT json_group_array(json(v) ORDER BY part, o) FROM (SELECT value AS v, 0 AS part, CAST(key AS INTEGER) AS o FROM json_each(section.json, '$.items') WHERE json_extract(value, '$.group') IS NOT 'stem' UNION ALL SELECT value, 1, CAST(key AS INTEGER) FROM json_each('[{"id":"the-gioi-robot","group":"stem","stage":"th-thcs","topic":"robotics","icon":"humanoid","title":"Thế giới robot","description":"Tám buổi đi từ robot hình người, mobile robot đến cánh tay robot trong sản xuất, khép lại bằng dự án cuối khóa."},{"id":"xe-robot-chuyen-sau","group":"stem","stage":"th-thcs","topic":"robotics","icon":"robot-car","title":"Khám phá xe robot","description":"Lập trình xe robot với mBlock qua cảm biến, màu sắc, âm thanh và chuyển động, khép lại bằng dự án cuối khóa."},{"id":"lap-trinh-ai","group":"stem","stage":"th-thcs","topic":"aiot","icon":"scratch","title":"Lập trình cùng AI","description":"Làm quen Pictoblox, lập trình trò chơi và AI cơ bản, rồi điều khiển nhân vật, tạo trợ lý ảo và xe tự hành."},{"id":"the-gioi-3d","group":"stem","stage":"th-thcs","topic":"aiot","icon":"process","title":"Chinh phục thế giới 3D","description":"Thiết kế 3D từ kiến trúc, nội thất đến con lắc Newton và nhân vật chuyển động với SimLab, khép lại bằng dự án cuối khóa."},{"id":"website-chuyen-sau","group":"stem","stage":"thpt","topic":"aiot","icon":"scratch","title":"Thiết kế website","description":"Thiết kế giao diện trong Figma với Gestalt, Grid, màu sắc, Typography, Component, AutoLayout và Prototype, hoàn thiện một Landing Page."},{"id":"ai-khoa-hoc-du-lieu","group":"stem","stage":"thpt","topic":"aiot","icon":"photonics","title":"AI và khoa học dữ liệu","description":"Từ trí tuệ nhân tạo và Python đến nhận diện vật thể với YOLO: huấn luyện, đánh giá mô hình và xây dựng ứng dụng AI."},{"id":"the-gioi-dien-tu","group":"stem","stage":"thpt","topic":"robotics","icon":"electronics","comingSoon":true,"title":"Thế giới điện tử","description":"Ba module Mini Drone, Mini Robot và IoT smart kit."}]')))) ELSE json_insert(json_set(json, '$.items', (SELECT json_group_array(json(v) ORDER BY part, o) FROM (SELECT value AS v, 0 AS part, CAST(key AS INTEGER) AS o FROM json_each(section.json, '$.items') WHERE json_extract(value, '$.group') IS NOT 'stem' UNION ALL SELECT value, 1, CAST(key AS INTEGER) FROM json_each('[{"id":"the-gioi-robot","group":"stem","stage":"th-thcs","topic":"robotics","icon":"humanoid","title":"Thế giới robot","description":"Tám buổi đi từ robot hình người, mobile robot đến cánh tay robot trong sản xuất, khép lại bằng dự án cuối khóa."},{"id":"xe-robot-chuyen-sau","group":"stem","stage":"th-thcs","topic":"robotics","icon":"robot-car","title":"Khám phá xe robot","description":"Lập trình xe robot với mBlock qua cảm biến, màu sắc, âm thanh và chuyển động, khép lại bằng dự án cuối khóa."},{"id":"lap-trinh-ai","group":"stem","stage":"th-thcs","topic":"aiot","icon":"scratch","title":"Lập trình cùng AI","description":"Làm quen Pictoblox, lập trình trò chơi và AI cơ bản, rồi điều khiển nhân vật, tạo trợ lý ảo và xe tự hành."},{"id":"the-gioi-3d","group":"stem","stage":"th-thcs","topic":"aiot","icon":"process","title":"Chinh phục thế giới 3D","description":"Thiết kế 3D từ kiến trúc, nội thất đến con lắc Newton và nhân vật chuyển động với SimLab, khép lại bằng dự án cuối khóa."},{"id":"website-chuyen-sau","group":"stem","stage":"thpt","topic":"aiot","icon":"scratch","title":"Thiết kế website","description":"Thiết kế giao diện trong Figma với Gestalt, Grid, màu sắc, Typography, Component, AutoLayout và Prototype, hoàn thiện một Landing Page."},{"id":"ai-khoa-hoc-du-lieu","group":"stem","stage":"thpt","topic":"aiot","icon":"photonics","title":"AI và khoa học dữ liệu","description":"Từ trí tuệ nhân tạo và Python đến nhận diện vật thể với YOLO: huấn luyện, đánh giá mô hình và xây dựng ứng dụng AI."},{"id":"the-gioi-dien-tu","group":"stem","stage":"thpt","topic":"robotics","icon":"electronics","comingSoon":true,"title":"Thế giới điện tử","description":"Ba module Mini Drone, Mini Robot và IoT smart kit."}]')))), '$.stages[#]', json('{"id":"th-thcs","short":"TH/THCS","label":"Tiểu học – THCS"}')) END, (SELECT '$.groups[' || key || '].description' FROM json_each(section.json, '$.groups') WHERE json_extract(value, '$.id') = 'stem' AND json_extract(value, '$.description') = 'Chương trình đầy đủ 5–10 tuần, theo một dự án từ bản phác đầu tiên đến sản phẩm hoàn thiện.'), 'Khóa học 8 buổi đi sâu một chủ đề robot hoặc AIoT, cho học sinh tiểu học – THCS và THPT.') ELSE CASE WHEN EXISTS (SELECT 1 FROM json_each(section.json, '$.stages') WHERE json_extract(value, '$.id') = 'th-thcs') THEN json_set(json, '$.items', (SELECT json_group_array(json(v) ORDER BY part, o) FROM (SELECT value AS v, 0 AS part, CAST(key AS INTEGER) AS o FROM json_each(section.json, '$.items') WHERE json_extract(value, '$.group') IS NOT 'stem' UNION ALL SELECT value, 1, CAST(key AS INTEGER) FROM json_each('[{"id":"the-gioi-robot","group":"stem","stage":"th-thcs","topic":"robotics","icon":"humanoid","title":"Thế giới robot","description":"Tám buổi đi từ robot hình người, mobile robot đến cánh tay robot trong sản xuất, khép lại bằng dự án cuối khóa."},{"id":"xe-robot-chuyen-sau","group":"stem","stage":"th-thcs","topic":"robotics","icon":"robot-car","title":"Khám phá xe robot","description":"Lập trình xe robot với mBlock qua cảm biến, màu sắc, âm thanh và chuyển động, khép lại bằng dự án cuối khóa."},{"id":"lap-trinh-ai","group":"stem","stage":"th-thcs","topic":"aiot","icon":"scratch","title":"Lập trình cùng AI","description":"Làm quen Pictoblox, lập trình trò chơi và AI cơ bản, rồi điều khiển nhân vật, tạo trợ lý ảo và xe tự hành."},{"id":"the-gioi-3d","group":"stem","stage":"th-thcs","topic":"aiot","icon":"process","title":"Chinh phục thế giới 3D","description":"Thiết kế 3D từ kiến trúc, nội thất đến con lắc Newton và nhân vật chuyển động với SimLab, khép lại bằng dự án cuối khóa."},{"id":"website-chuyen-sau","group":"stem","stage":"thpt","topic":"aiot","icon":"scratch","title":"Thiết kế website","description":"Thiết kế giao diện trong Figma với Gestalt, Grid, màu sắc, Typography, Component, AutoLayout và Prototype, hoàn thiện một Landing Page."},{"id":"ai-khoa-hoc-du-lieu","group":"stem","stage":"thpt","topic":"aiot","icon":"photonics","title":"AI và khoa học dữ liệu","description":"Từ trí tuệ nhân tạo và Python đến nhận diện vật thể với YOLO: huấn luyện, đánh giá mô hình và xây dựng ứng dụng AI."},{"id":"the-gioi-dien-tu","group":"stem","stage":"thpt","topic":"robotics","icon":"electronics","comingSoon":true,"title":"Thế giới điện tử","description":"Ba module Mini Drone, Mini Robot và IoT smart kit."}]')))) ELSE json_insert(json_set(json, '$.items', (SELECT json_group_array(json(v) ORDER BY part, o) FROM (SELECT value AS v, 0 AS part, CAST(key AS INTEGER) AS o FROM json_each(section.json, '$.items') WHERE json_extract(value, '$.group') IS NOT 'stem' UNION ALL SELECT value, 1, CAST(key AS INTEGER) FROM json_each('[{"id":"the-gioi-robot","group":"stem","stage":"th-thcs","topic":"robotics","icon":"humanoid","title":"Thế giới robot","description":"Tám buổi đi từ robot hình người, mobile robot đến cánh tay robot trong sản xuất, khép lại bằng dự án cuối khóa."},{"id":"xe-robot-chuyen-sau","group":"stem","stage":"th-thcs","topic":"robotics","icon":"robot-car","title":"Khám phá xe robot","description":"Lập trình xe robot với mBlock qua cảm biến, màu sắc, âm thanh và chuyển động, khép lại bằng dự án cuối khóa."},{"id":"lap-trinh-ai","group":"stem","stage":"th-thcs","topic":"aiot","icon":"scratch","title":"Lập trình cùng AI","description":"Làm quen Pictoblox, lập trình trò chơi và AI cơ bản, rồi điều khiển nhân vật, tạo trợ lý ảo và xe tự hành."},{"id":"the-gioi-3d","group":"stem","stage":"th-thcs","topic":"aiot","icon":"process","title":"Chinh phục thế giới 3D","description":"Thiết kế 3D từ kiến trúc, nội thất đến con lắc Newton và nhân vật chuyển động với SimLab, khép lại bằng dự án cuối khóa."},{"id":"website-chuyen-sau","group":"stem","stage":"thpt","topic":"aiot","icon":"scratch","title":"Thiết kế website","description":"Thiết kế giao diện trong Figma với Gestalt, Grid, màu sắc, Typography, Component, AutoLayout và Prototype, hoàn thiện một Landing Page."},{"id":"ai-khoa-hoc-du-lieu","group":"stem","stage":"thpt","topic":"aiot","icon":"photonics","title":"AI và khoa học dữ liệu","description":"Từ trí tuệ nhân tạo và Python đến nhận diện vật thể với YOLO: huấn luyện, đánh giá mô hình và xây dựng ứng dụng AI."},{"id":"the-gioi-dien-tu","group":"stem","stage":"thpt","topic":"robotics","icon":"electronics","comingSoon":true,"title":"Thế giới điện tử","description":"Ba module Mini Drone, Mini Robot và IoT smart kit."}]')))), '$.stages[#]', json('{"id":"th-thcs","short":"TH/THCS","label":"Tiểu học – THCS"}')) END END, '$.comingSoon', 'Sắp ra mắt'),
       rev = rev + 1,
       updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
 WHERE key = 'courses' AND locale = 'vi'
   AND NOT EXISTS (SELECT 1 FROM json_each(section.json, '$.items') WHERE json_extract(value, '$.id') = 'the-gioi-robot');

-- en
UPDATE section
   SET json = json_set(CASE WHEN (SELECT '$.groups[' || key || '].description' FROM json_each(section.json, '$.groups') WHERE json_extract(value, '$.id') = 'stem' AND json_extract(value, '$.description') = 'Full programmes of 5–10 weeks, carrying one project from first sketch through to a finished build.') IS NOT NULL THEN json_set(CASE WHEN EXISTS (SELECT 1 FROM json_each(section.json, '$.stages') WHERE json_extract(value, '$.id') = 'th-thcs') THEN json_set(json, '$.items', (SELECT json_group_array(json(v) ORDER BY part, o) FROM (SELECT value AS v, 0 AS part, CAST(key AS INTEGER) AS o FROM json_each(section.json, '$.items') WHERE json_extract(value, '$.group') IS NOT 'stem' UNION ALL SELECT value, 1, CAST(key AS INTEGER) FROM json_each('[{"id":"the-gioi-robot","group":"stem","stage":"th-thcs","topic":"robotics","icon":"humanoid","title":"World of Robots","description":"Eight sessions from humanoid robots and mobile robots to robotic arms in manufacturing, wrapped up with a final project."},{"id":"xe-robot-chuyen-sau","group":"stem","stage":"th-thcs","topic":"robotics","icon":"robot-car","title":"Robot Car Discovery","description":"Program a robot car in mBlock through sensors, colours, sound and motion, wrapped up with a final project."},{"id":"lap-trinh-ai","group":"stem","stage":"th-thcs","topic":"aiot","icon":"scratch","title":"Coding with AI","description":"Get started with Pictoblox, code games and basic AI, then control characters, build a virtual assistant and a self-driving car."},{"id":"the-gioi-3d","group":"stem","stage":"th-thcs","topic":"aiot","icon":"process","title":"Conquering the 3D World","description":"3D design from architecture and interiors to a Newton''s cradle and animated characters in SimLab, wrapped up with a final project."},{"id":"website-chuyen-sau","group":"stem","stage":"thpt","topic":"aiot","icon":"scratch","title":"Website Design","description":"Interface design in Figma with Gestalt, grids, colour, typography, components, AutoLayout and prototypes, finishing with a landing page."},{"id":"ai-khoa-hoc-du-lieu","group":"stem","stage":"thpt","topic":"aiot","icon":"photonics","title":"AI and Data Science","description":"From artificial intelligence and Python to object detection with YOLO: training and evaluating models and building an AI app."},{"id":"the-gioi-dien-tu","group":"stem","stage":"thpt","topic":"robotics","icon":"electronics","comingSoon":true,"title":"World of Electronics","description":"Three modules: Mini Drone, Mini Robot and IoT smart kit."}]')))) ELSE json_insert(json_set(json, '$.items', (SELECT json_group_array(json(v) ORDER BY part, o) FROM (SELECT value AS v, 0 AS part, CAST(key AS INTEGER) AS o FROM json_each(section.json, '$.items') WHERE json_extract(value, '$.group') IS NOT 'stem' UNION ALL SELECT value, 1, CAST(key AS INTEGER) FROM json_each('[{"id":"the-gioi-robot","group":"stem","stage":"th-thcs","topic":"robotics","icon":"humanoid","title":"World of Robots","description":"Eight sessions from humanoid robots and mobile robots to robotic arms in manufacturing, wrapped up with a final project."},{"id":"xe-robot-chuyen-sau","group":"stem","stage":"th-thcs","topic":"robotics","icon":"robot-car","title":"Robot Car Discovery","description":"Program a robot car in mBlock through sensors, colours, sound and motion, wrapped up with a final project."},{"id":"lap-trinh-ai","group":"stem","stage":"th-thcs","topic":"aiot","icon":"scratch","title":"Coding with AI","description":"Get started with Pictoblox, code games and basic AI, then control characters, build a virtual assistant and a self-driving car."},{"id":"the-gioi-3d","group":"stem","stage":"th-thcs","topic":"aiot","icon":"process","title":"Conquering the 3D World","description":"3D design from architecture and interiors to a Newton''s cradle and animated characters in SimLab, wrapped up with a final project."},{"id":"website-chuyen-sau","group":"stem","stage":"thpt","topic":"aiot","icon":"scratch","title":"Website Design","description":"Interface design in Figma with Gestalt, grids, colour, typography, components, AutoLayout and prototypes, finishing with a landing page."},{"id":"ai-khoa-hoc-du-lieu","group":"stem","stage":"thpt","topic":"aiot","icon":"photonics","title":"AI and Data Science","description":"From artificial intelligence and Python to object detection with YOLO: training and evaluating models and building an AI app."},{"id":"the-gioi-dien-tu","group":"stem","stage":"thpt","topic":"robotics","icon":"electronics","comingSoon":true,"title":"World of Electronics","description":"Three modules: Mini Drone, Mini Robot and IoT smart kit."}]')))), '$.stages[#]', json('{"id":"th-thcs","short":"Primary/Secondary","label":"Primary & lower secondary"}')) END, (SELECT '$.groups[' || key || '].description' FROM json_each(section.json, '$.groups') WHERE json_extract(value, '$.id') = 'stem' AND json_extract(value, '$.description') = 'Full programmes of 5–10 weeks, carrying one project from first sketch through to a finished build.'), 'Eight-session courses that go deep into one robotics or AIoT topic, for primary, lower and upper secondary students.') ELSE CASE WHEN EXISTS (SELECT 1 FROM json_each(section.json, '$.stages') WHERE json_extract(value, '$.id') = 'th-thcs') THEN json_set(json, '$.items', (SELECT json_group_array(json(v) ORDER BY part, o) FROM (SELECT value AS v, 0 AS part, CAST(key AS INTEGER) AS o FROM json_each(section.json, '$.items') WHERE json_extract(value, '$.group') IS NOT 'stem' UNION ALL SELECT value, 1, CAST(key AS INTEGER) FROM json_each('[{"id":"the-gioi-robot","group":"stem","stage":"th-thcs","topic":"robotics","icon":"humanoid","title":"World of Robots","description":"Eight sessions from humanoid robots and mobile robots to robotic arms in manufacturing, wrapped up with a final project."},{"id":"xe-robot-chuyen-sau","group":"stem","stage":"th-thcs","topic":"robotics","icon":"robot-car","title":"Robot Car Discovery","description":"Program a robot car in mBlock through sensors, colours, sound and motion, wrapped up with a final project."},{"id":"lap-trinh-ai","group":"stem","stage":"th-thcs","topic":"aiot","icon":"scratch","title":"Coding with AI","description":"Get started with Pictoblox, code games and basic AI, then control characters, build a virtual assistant and a self-driving car."},{"id":"the-gioi-3d","group":"stem","stage":"th-thcs","topic":"aiot","icon":"process","title":"Conquering the 3D World","description":"3D design from architecture and interiors to a Newton''s cradle and animated characters in SimLab, wrapped up with a final project."},{"id":"website-chuyen-sau","group":"stem","stage":"thpt","topic":"aiot","icon":"scratch","title":"Website Design","description":"Interface design in Figma with Gestalt, grids, colour, typography, components, AutoLayout and prototypes, finishing with a landing page."},{"id":"ai-khoa-hoc-du-lieu","group":"stem","stage":"thpt","topic":"aiot","icon":"photonics","title":"AI and Data Science","description":"From artificial intelligence and Python to object detection with YOLO: training and evaluating models and building an AI app."},{"id":"the-gioi-dien-tu","group":"stem","stage":"thpt","topic":"robotics","icon":"electronics","comingSoon":true,"title":"World of Electronics","description":"Three modules: Mini Drone, Mini Robot and IoT smart kit."}]')))) ELSE json_insert(json_set(json, '$.items', (SELECT json_group_array(json(v) ORDER BY part, o) FROM (SELECT value AS v, 0 AS part, CAST(key AS INTEGER) AS o FROM json_each(section.json, '$.items') WHERE json_extract(value, '$.group') IS NOT 'stem' UNION ALL SELECT value, 1, CAST(key AS INTEGER) FROM json_each('[{"id":"the-gioi-robot","group":"stem","stage":"th-thcs","topic":"robotics","icon":"humanoid","title":"World of Robots","description":"Eight sessions from humanoid robots and mobile robots to robotic arms in manufacturing, wrapped up with a final project."},{"id":"xe-robot-chuyen-sau","group":"stem","stage":"th-thcs","topic":"robotics","icon":"robot-car","title":"Robot Car Discovery","description":"Program a robot car in mBlock through sensors, colours, sound and motion, wrapped up with a final project."},{"id":"lap-trinh-ai","group":"stem","stage":"th-thcs","topic":"aiot","icon":"scratch","title":"Coding with AI","description":"Get started with Pictoblox, code games and basic AI, then control characters, build a virtual assistant and a self-driving car."},{"id":"the-gioi-3d","group":"stem","stage":"th-thcs","topic":"aiot","icon":"process","title":"Conquering the 3D World","description":"3D design from architecture and interiors to a Newton''s cradle and animated characters in SimLab, wrapped up with a final project."},{"id":"website-chuyen-sau","group":"stem","stage":"thpt","topic":"aiot","icon":"scratch","title":"Website Design","description":"Interface design in Figma with Gestalt, grids, colour, typography, components, AutoLayout and prototypes, finishing with a landing page."},{"id":"ai-khoa-hoc-du-lieu","group":"stem","stage":"thpt","topic":"aiot","icon":"photonics","title":"AI and Data Science","description":"From artificial intelligence and Python to object detection with YOLO: training and evaluating models and building an AI app."},{"id":"the-gioi-dien-tu","group":"stem","stage":"thpt","topic":"robotics","icon":"electronics","comingSoon":true,"title":"World of Electronics","description":"Three modules: Mini Drone, Mini Robot and IoT smart kit."}]')))), '$.stages[#]', json('{"id":"th-thcs","short":"Primary/Secondary","label":"Primary & lower secondary"}')) END END, '$.comingSoon', 'Coming soon'),
       rev = rev + 1,
       updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
 WHERE key = 'courses' AND locale = 'en'
   AND NOT EXISTS (SELECT 1 FROM json_each(section.json, '$.items') WHERE json_extract(value, '$.id') = 'the-gioi-robot');

INSERT OR IGNORE INTO course_detail (locale, course_id, source, json, updated_at)
SELECT 'vi', 'the-gioi-robot', 'handwritten', '{"audience":"học sinh tiểu học và THCS","curriculum":["Buổi 1 – Khám phá thế giới robot","Buổi 2 – Robot hình người","Buổi 3 – Mobile robot 1","Buổi 4 – Mobile robot 2","Buổi 5 – Cánh tay robot trong sản xuất 1","Buổi 6 – Cánh tay robot trong sản xuất 2","Buổi 7 – Ý tưởng dự án","Buổi 8 – Dự án cuối khóa"]}', strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
 WHERE EXISTS (SELECT 1 FROM section);
